public static void main(String[] args) throws IOException {
    BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
    int N = Integer.parseInt(reader.readLine().trim());
    int count = 0;
    Map<Integer, Integer> firstAppearanceIndex = new HashMap<>();
    String[] inputs = reader.readLine().trim().split("\\s+");

    for (int i = 0; i < 2 * N; i++) {
        int input = Integer.parseInt(inputs[i]);
        if (!firstAppearanceIndex.containsKey(input)) {
            firstAppearanceIndex.put(input, i);
        } else {
            if (i - firstAppearanceIndex.get(input) == 3) {
                count++;
            }
        }
    }
    System.out.println(count);
}
